    slug: 'visita-papa-leon-xiv-madrid-llave-oro-noche-blanco-museos',
    title: 'Visita del Papa León XIV a Madrid 2026: «Llave de Oro», 21 actos y la «Noche en Blanco» papal',
    excerpt: 'El Papa León XIV permanecerá en Madrid del 6 al 9 de junio con una agenda de 21 actos. El alcalde José Luis Martínez-Almeida entregará al Pontífice la «Llave de Oro de la Villa» en Cibeles, reproduciendo la tradición de la visita de Benedicto XVI en 2011. El sábado 6 de junio, 15 museos municipales abrirán gratuitamente con horario ampliado en una «Noche en Blanco» papal.',
    content: 'El Papa León XIV permanecerá en Madrid del 6 al 9 de junio de 2026 con una agenda intensiva de veintiún actos. La visita marca el regreso papal a la capital tras quince años, siendo la primera desde el viaje de Benedicto XVI con motivo de la JMJ de 2011. Como gesto institucional destacado, el alcalde José Luis Martínez-Almeida entregará al Pontífice la «Llave de Oro de la Villa» en la Plaza de Cibeles, reproduciendo la tradición de la visita de 2011. El lunes 8 de junio, el Papa se dirigirá por primera vez en la historia tanto al Congreso de los Diputados como al Senado en sesión conjunta. El Movistar Arena albergará el encuentro «Tejer redes con el mundo de la cultura, el arte, la economía y el deporte», y el acto multitudinario del Estadio Santiago Bernabéu contará con actuaciones de David Bustamante, Daniel Diges y Diana Navarro, acompañados por un coro de mil voces. El Ayuntamiento de Madrid celebrará el sábado 6 una «Noche en Blanco» con motivo del viaje, en la que quince museos municipales abrirán gratuitamente con horario ampliado.',
    date: '2026-05-09',
    source: 'elDiario.es',
    sourceUrl: 'https://www.eldiario.es/madrid/somos/agenda/visita-papa-leon-xiv-madrid-2026-fechas-actos-publicos-agenda-completa-viaje-apostolico_1_13212283.html',
    relatedCities: ['madrid'],
