    title: 'Visita del Papa León XIV a España: cuarto viaje apostólico del pontificado e histórica intervención parlamentaria',
    excerpt: 'El Papa León XIV realizará del 6 al 12 de junio de 2026 su cuarto viaje apostólico oficial al extranjero, y el primero a España de un Pontífice desde Benedicto XVI en 2011. El itinerario combina actos institucionales en Madrid (incluyendo la primera intervención de un Papa ante el Parlamento español) con iniciativas pastorales centradas en colectivos vulnerables: personas sin hogar, internos del Centro Penitenciario Brians 1 y migrantes en Canarias.',
    content: 'El viaje apostólico del Papa León XIV a España, del 6 al 12 de junio de 2026, será el cuarto viaje internacional oficial de su pontificado y el primero de un Pontífice al país desde la JMJ de Benedicto XVI en 2011. El itinerario incluye Madrid, Barcelona, Gran Canaria y Tenerife, combinando actos institucionales con iniciativas pastorales centradas en colectivos vulnerables. Entre los hitos históricos destaca la primera intervención de un Papa ante el Parlamento español, prevista para el lunes 8 de junio en sesión conjunta del Congreso y el Senado. El miércoles 10 de junio el Pontífice presidirá la Eucaristía en la Basílica de la Sagrada Familia con la inauguración de la Torre de Jesucristo, lo que convertirá al templo en la iglesia más alta del mundo, coincidiendo con el centenario de la muerte de Antoni Gaudí. La agenda incluye la visita al Centro Penitenciario Brians 1 (Sant Esteve Sesrovires) y encuentros con asociaciones de acogida a migrantes en el muelle de Arguineguín y en el centro Las Raíces de Tenerife, en continuidad con el viaje del Papa a África dos meses antes y con el magisterio social de León XIV sobre la dignidad humana.',
